mapper.select:
SELECT FINPROD_MARKET_ID id, FINPROD_NAME text, CONCAT_WS('',FIN_PRODUCT.FINPROD_ID, ',' , FIN_PRODUCT_ADD.DEAL_MODE) object FROM FIN_PRODUCT INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_PRODUCT.FINPROD_ID
INNER JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userName} WHERE FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F16, jdbcType = VARCHAR} AND PROFIT_TYPE = #{PROFIT_TYPE_01, jdbcType = VARCHAR}
AND FINPROD_MARKET_ID LIKE CONCAT('%',#{search},'%')

SELECT A.BONUS_PLAN_ID bonusPlanId, A.BONU_SCALC_FLAG bonuScalcFlag, A.DEL_DATE delDate, A.REG_DATE regDate, A.VLU_REF_DATE vluRefDate, A.UNIT_BONUS_VLU unitBonusVlu, A.TOTAL_AMT totalAmt, A.REMARK remark, A.BASE_DATE baseDate, A.BONUS_DATE bonusDate, (CASE WHEN B.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F24,jdbcType = VARCHAR} THEN B.FINPROD_ID ELSE '' END) prodStyle, B.FINPROD_NAME finprodName, (CASE WHEN B.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F24,jdbcType = VARCHAR} THEN B.P_FINPROD_ID ELSE B.FINPROD_ID END) finprodId, B.FINPROD_MARKET_ID finprodMarketId, B.FINPROD_ABBR finprodAbbr, b.CCY,
D1.FPRICE_AMT actTotalAmt, D2.bonusCashAmt, D3.bonusShareAmt, D3.bonusShareNum, D1.TRADE_ID bTradeId, PBSI.SEND_STATUS sendStatus, PBSI.SEND_REMARK sendRemark FROM PRD_BONUS_PLAN_N A INNER JOIN FIN_PRODUCT B ON A.FINPROD_ID = B.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL D1 ON A.BONUS_PLAN_ID=D1.B_TRADE_ID AND D1.BUSI_TYPE=#{BUSI_TYPE,jdbcType = VARCHAR} AND D1.FINPROD_TYPE2 in (#{FINPROD_TYPE_TG_F16,jdbcType = VARCHAR},#{FINPROD_TYPE_TG_F24,jdbcType = VARCHAR}) AND D1.PS='C8' AND D1.TRADE_STATUS='01'
LEFT JOIN (SELECT D1.B_TRADE_ID,D1.FINPROD_ID,SUM(IFNULL(D1.TRADE_AMT,0)) bonusCashAmt FROM TRD_PRODUCT_DEAL D1 WHERE D1.BUSI_TYPE=#{BUSI_TYPE,jdbcType = VARCHAR} AND D1.FINPROD_TYPE2 in (#{FINPROD_TYPE_TG_F16,jdbcType = VARCHAR},#{FINPROD_TYPE_TG_F24,jdbcType = VARCHAR}) AND D1.PS='C9' AND D1.TRADE_STATUS='01' GROUP BY D1.B_TRADE_ID,D1.FINPROD_ID ) D2 ON D1.TRADE_ID=D2.B_TRADE_ID
LEFT JOIN (SELECT D1.B_TRADE_ID,D1.FINPROD_ID,SUM(IFNULL(D1.TRADE_AMT,0)) bonusShareAmt,SUM(IFNULL(SHARE_AMT,0)) bonusShareNum FROM TRD_PRODUCT_DEAL D1 WHERE D1.BUSI_TYPE=#{BUSI_TYPE,jdbcType = VARCHAR}
AND D1.FINPROD_TYPE2 in (#{FINPROD_TYPE_TG_F16,jdbcType = VARCHAR},#{FINPROD_TYPE_TG_F24,jdbcType = VARCHAR},#{FINPROD_TYPE_TG_F26,jdbcType = VARCHAR}) AND D1.PS='C10' AND D1.TRADE_STATUS='01' GROUP BY D1.B_TRADE_ID,D1.FINPROD_ID ) D3 ON D1.TRADE_ID=D3.B_TRADE_ID
LEFT JOIN INF_PRD_BONUS_PLAN_N PBSI ON A.BONUS_PLAN_ID = PBSI.BONUS_PLAN_ID
WHERE B.FINPROD_TYPE2 in (#{FINPROD_TYPE_TG_F16,jdbcType = VARCHAR},#{FINPROD_TYPE_TG_F24,jdbcType = VARCHAR})
AND DATE_FORMAT(A.DEL_DATE,'%Y-%m-%d') > = #{startDelDate}
AND DATE_FORMAT(A.DEL_DATE,'%Y-%m-%d') < = #{endDelDate}
AND DATE_FORMAT(A.REG_DATE,'%Y-%m-%d') > = #{startRegDate}
AND DATE_FORMAT(A.REG_DATE,'%Y-%m-%d') < = #{endRegDate}
AND DATE_FORMAT(A.VLU_REF_DATE,'%Y-%m-%d') > = #{startVluRefDate}
AND DATE_FORMAT(A.VLU_REF_DATE,'%Y-%m-%d') < = #{endVluRefDate}
AND B.FINPROD_MARKET_ID= #{finprodMarketId,jdbcType=VARCHAR}
AND B.FINPROD_ID= #{prodStyle,jdbcType=VARCHAR}
AND IFNULL(PBSI.SEND_STATUS, '03') = #{sendStatus,jdbcType=VARCHAR}
AND PBSI.SEND_REMARK = #{sendRemark,jdbcType=VARCHAR}

SELECT distinct A.FINPROD_MARKET_ID id, A.FINPROD_NAME text, CONCAT_WS('', A.FINPROD_ABBR , ',', A.FINPROD_NAME , ',' , A.FINPROD_ID , ',' , B.UNITVALUE_DEC , ',' , C.PUR_SPEED,',', A.CCY , ',' , D.DEAL_MODE ,',', PTL.PORTFOLIO_ID ) object FROM FIN_PRODUCT A INNER JOIN PTL_MANAGE_OBJ PTL ON PTL.MANAGE_OBJ_ID = A.FINPROD_ID
INNER JOIN FIN_PRODUCT_ADD D ON A.FINPROD_ID = D.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PTLAUTH ON PTL.PORTFOLIO_ID = PTLAUTH.PORTFOLIO_ID, PRD_VAL_PARAM B,FIN_PRODUCT_ADD C WHERE A.FINPROD_ID = B.FINPROD_ID AND A.FINPROD_ID = C.FINPROD_ID AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F16, jdbcType = VARCHAR} AND A.PROFIT_TYPE = #{PROFIT_TYPE_01, jdbcType = VARCHAR}
AND A.FINPROD_MARKET_ID LIKE CONCAT('%',#{search},'%')
AND A.FINPROD_MARKET_ID = #{initValue,jdbcType=VARCHAR}
AND PTLAUTH.USER_ID = #{userName}

SELECT
TRADE_ID
FROM
TRD_PRODUCT_DEAL
WHERE
TRADE_STATUS = #{TRADE_STATUS_01, jdbcType = VARCHAR}
AND IS_CANCEL = #{YES_OR_NO_N, jdbcType = VARCHAR}
AND PS = #{PS_C8, jdbcType = VARCHAR}
AND FINPROD_ID = #{finprodId, jdbcType = VARCHAR}
AND DATE_FORMAT(TRADE_DATE,'%Y-%m-%d') = #{delDate}

SELECT
COUNT(BONUS_PLAN_ID)
FROM
PRD_BONUS_PLAN_N
WHERE
DATE_FORMAT(DEL_DATE,'%Y-%m-%d') = #{delDate}
AND FINPROD_ID = #{finprodId, jdbcType = VARCHAR}

	AND BONUS_PLAN_ID !=  #{bonusPlanId,jdbcType=VARCHAR}

SELECT A.BONU_SCALC_FLAG, A.BONUS_PLAN_ID, A.BASE_DATE, A.DEL_DATE, A.REG_DATE, A.VLU_REF_DATE, A.BONUS_DATE, A.UNIT_BONUS_VLU, A.TOTAL_AMT, A.IS_NET_MORMALIZE, A.REMARK, B.FINPROD_MARKET_ID, B.FINPROD_ABBR, B.FINPROD_NAME,
B.LIQUIDATION_YESNO, (CASE WHEN B.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F24,jdbcType = VARCHAR} THEN B.P_FINPROD_ID ELSE B.FINPROD_ID END) FINPROD_ID, (CASE WHEN B.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F24,jdbcType = VARCHAR} THEN B.FINPROD_ID ELSE '') prodStyle, padd.PORTFOLIO_ID portfolioId, C.TDY_UNPAID_INTINCEXP, Round(D.TDY_UNIT_VALUE,4) TDY_UNIT_VALUE, ROUND(BD.TDY_UNIT_VALUE,4) shareTdyUnitValue, D.TDY_SHARE_AMT, B.CCY, D1.actTotalAmt, D1.actUnitBonusVlu, IFNULL(d1.regDateNum, E.TDY_SHARE_AMT) regDateNum, D2.totalBonusCashAmt, D1.TRADE_ID bTradeId, --update by leipeng BSTWO-81 【分红方案登记�?�返回查看，基准日未分配利润余不应显示为�? (C.TDY_ASSET_AMT - C.TDY_SHARE_AMT) tdyUnpaidIntincexp, padd.IS_CYCLE isCycle FROM PRD_BONUS_PLAN_N A LEFT JOIN FIN_PRODUCT B ON A.FINPROD_ID = B.FINPROD_ID LEFT JOIN BOK_POSITION_PRD C ON A.FINPROD_ID = C.FINPROD_ID AND DATE_FORMAT(A.BASE_DATE,'%Y-%m-%d') = DATE_FORMAT(C.CDATE,'%Y-%m-%d') LEFT JOIN BOK_POSITION_PRD D ON A.FINPROD_ID = D.FINPROD_ID AND DATE_FORMAT(A.VLU_REF_DATE,'%Y-%m-%d') = DATE_FORMAT(D.CDATE,'%Y-%m-%d')
LEFT JOIN BOK_POSITION_PRD BD ON A.FINPROD_ID = BD.FINPROD_ID AND DATE_FORMAT(A.DEL_DATE,'%Y-%m-%d') = DATE_FORMAT(BD.CDATE,'%Y-%m-%d')
LEFT JOIN BOK_POSITION_PRD E ON A.FINPROD_ID = E.FINPROD_ID AND A.REG_DATE = E.CDATE LEFT JOIN (SELECT D1.TRADE_ID,D1.B_TRADE_ID,D1.FINPROD_ID,
D1.FPRICE_AMT actTotalAmt, d1.unit_int actUnitBonusVlu,d1.SHARE_AMT regDateNum FROM TRD_PRODUCT_DEAL D1 WHERE D1.BUSI_TYPE=#{BUSI_TYPE,jdbcType = VARCHAR}
AND D1.FINPROD_TYPE2 in (#{FINPROD_TYPE_TG_F16,jdbcType = VARCHAR}, #{FINPROD_TYPE_TG_F24,jdbcType = VARCHAR}) AND D1.PS='C8' AND D1.TRADE_STATUS='01' ) D1 ON A.BONUS_PLAN_ID=D1.B_TRADE_ID LEFT JOIN (SELECT D1.B_TRADE_ID,D1.FINPROD_ID,SUM(IFNULL(D1.TRADE_AMT,0)) totalBonusCashAmt FROM TRD_PRODUCT_DEAL D1 WHERE D1.BUSI_TYPE=#{BUSI_TYPE,jdbcType = VARCHAR}
AND D1.FINPROD_TYPE2 in (#{FINPROD_TYPE_TG_F16,jdbcType = VARCHAR}, #{FINPROD_TYPE_TG_F24,jdbcType = VARCHAR}) AND D1.PS in('C9','C10') AND D1.TRADE_STATUS='01' GROUP BY D1.B_TRADE_ID,D1.FINPROD_ID ) D2 ON D1.TRADE_ID=D2.B_TRADE_ID left join FIN_PRODUCT_ADD padd ON padd.FINPROD_ID = b.FINPROD_ID WHERE
B.FINPROD_TYPE2 in (#{FINPROD_TYPE_TG_F16,jdbcType = VARCHAR}, #{FINPROD_TYPE_TG_F24,jdbcType = VARCHAR}) AND B.PROFIT_TYPE = #{PROFIT_TYPE_01, jdbcType = VARCHAR} AND A.BONUS_PLAN_ID = #{bonusPlanId, jdbcType = VARCHAR}

select r.pay_type
from FIN_CASH_PAY_RULE r
inner join fin_cash_info c on r.cash_id = c.cash_id
where c.finprod_id = #{finprodId, jdbcType = VARCHAR}
AND c.CASH_TYPE_1 = #{cashType1}
AND c.CASH_TYPE_2 = #{cashType2}
LIMIT 1

select * from (select plan.bonus_plan_id
from PRD_BONUS_PLAN_N plan

	inner join TRD_PRODUCT_DEAL deal1 on deal1.b_trade_id = plan.bonus_plan_id and deal1.ps='C8'
	where deal1.trade_id=#{tradeId,jdbcType=VARCHAR}


	inner join TRD_PRODUCT_DEAL deal1 on deal1.b_trade_id = plan.bonus_plan_id and deal1.ps='C8'
	inner join TRD_PRODUCT_DEAL deal2 on deal2.b_trade_id = deal1.trade_id and  deal2.ps ='C9'
	where deal2.trade_id=#{tradeId,jdbcType=VARCHAR}


	inner join TRD_PRODUCT_DEAL deal1 on deal1.b_trade_id = plan.bonus_plan_id and deal1.ps='C8'
	inner join TRD_PRODUCT_DEAL deal2 on deal2.b_trade_id = deal1.trade_id and  deal2.ps ='C10'
	where deal2.trade_id=#{tradeId,jdbcType=VARCHAR}

) where LIMIT 1

select * from (
select deal.trade_id tradeId, deal.finprod_id finprodId, pro.finprod_market_id finprodMarketId, padd.PORTFOLIO_ID portfolioId, deal.ccy, plan.BONU_SCALC_FLAG, plan.BONUS_PLAN_ID, plan.BASE_DATE, plan.DEL_DATE, plan.REG_DATE, plan.VLU_REF_DATE, plan.BONUS_DATE, plan.UNIT_BONUS_VLU, plan.TOTAL_AMT, plan.IS_NET_MORMALIZE, C.TDY_UNPAID_INTINCEXP, D.TDY_UNIT_VALUE, D.TDY_SHARE_AMT, deal.Settle_Date confirmDate, deal.unit_cprice tdyUnitValue, deal.trade_amt actTotalAmt from trd_product_deal deal inner join FIN_PRODUCT pro on deal.finprod_id=pro.finprod_id inner join FIN_PRODUCT_ADD padd on padd.finprod_id=pro.finprod_id inner join PRD_BONUS_PLAN_N plan on deal.b_trade_id = plan.bonus_plan_id LEFT JOIN BOK_POSITION_PRD C ON plan.FINPROD_ID = C.FINPROD_ID AND DATE_FORMAT(plan.BASE_DATE,'%Y-%m-%d') = DATE_FORMAT(C.CDATE,'%Y-%m-%d') LEFT JOIN BOK_POSITION_PRD D ON plan.FINPROD_ID = D.FINPROD_ID AND DATE_FORMAT(plan.VLU_REF_DATE,'%Y-%m-%d') = DATE_FORMAT(D.CDATE,'%Y-%m-%d') where deal.busi_type = '17' and deal.ps = 'C8' and deal.trade_id = #{tradeId, jdbcType = VARCHAR}
select deal.trade_id tradeId, deal.finprod_id finprodId, pro.finprod_market_id finprodMarketId, padd.PORTFOLIO_ID portfolioId, deal.ccy, plan.BONU_SCALC_FLAG, plan.BONUS_PLAN_ID, plan.BASE_DATE, plan.DEL_DATE, plan.REG_DATE, plan.VLU_REF_DATE, plan.BONUS_DATE, plan.UNIT_BONUS_VLU, plan.TOTAL_AMT, plan.IS_NET_MORMALIZE, C.TDY_UNPAID_INTINCEXP, D.TDY_UNIT_VALUE, D.TDY_SHARE_AMT, deal.Settle_Date actBonusDate, deal.trade_amt bonusCashAmt, deal.remark bonusDealRemark, deal0.trade_amt actTotalAmt, deal0.unit_int actUnitBonusVlu, deal0.remark from trd_product_deal deal inner join FIN_PRODUCT pro on deal.finprod_id=pro.finprod_id inner join FIN_PRODUCT_ADD padd on padd.finprod_id=pro.finprod_id inner join trd_product_deal deal0 on deal.b_trade_id=deal0.trade_id and deal0.ps = 'C8' inner join PRD_BONUS_PLAN_N plan on deal0.b_trade_id = plan.bonus_plan_id LEFT JOIN BOK_POSITION_PRD C ON plan.FINPROD_ID = C.FINPROD_ID AND DATE_FORMAT(plan.BASE_DATE,'%Y-%m-%d') = DATE_FORMAT(C.CDATE,'%Y-%m-%d') LEFT JOIN BOK_POSITION_PRD D ON plan.FINPROD_ID = D.FINPROD_ID AND DATE_FORMAT(plan.VLU_REF_DATE,'%Y-%m-%d') = DATE_FORMAT(D.CDATE,'%Y-%m-%d') where deal.busi_type = '17' and deal.ps = 'C9' and deal.trade_id = #{tradeId, jdbcType = VARCHAR}
select deal.trade_id tradeId, deal.finprod_id finprodId, pro.finprod_market_id finprodMarketId, padd.PORTFOLIO_ID portfolioId, deal.ccy, plan.BONU_SCALC_FLAG, plan.BONUS_PLAN_ID, plan.BASE_DATE, plan.DEL_DATE, plan.REG_DATE, plan.VLU_REF_DATE, plan.BONUS_DATE, plan.UNIT_BONUS_VLU, plan.TOTAL_AMT, plan.IS_NET_MORMALIZE, C.TDY_UNPAID_INTINCEXP, D.TDY_UNIT_VALUE, D.TDY_SHARE_AMT, deal.Settle_Date confirmDate, deal.unit_cprice tdyUnitValue, deal.trade_amt bonusShareAmt, deal.share_amt bonusShareNum from trd_product_deal deal inner join FIN_PRODUCT pro on deal.finprod_id=pro.finprod_id inner join FIN_PRODUCT_ADD padd on padd.finprod_id=pro.finprod_id inner join trd_product_deal deal0 on deal.b_trade_id=deal0.trade_id and deal0.ps = 'C8' inner join PRD_BONUS_PLAN_N plan on deal0.b_trade_id = plan.bonus_plan_id LEFT JOIN BOK_POSITION_PRD C ON plan.FINPROD_ID = C.FINPROD_ID AND DATE_FORMAT(plan.BASE_DATE,'%Y-%m-%d') = DATE_FORMAT(C.CDATE,'%Y-%m-%d') LEFT JOIN BOK_POSITION_PRD D ON plan.FINPROD_ID = D.FINPROD_ID AND DATE_FORMAT(plan.VLU_REF_DATE,'%Y-%m-%d') = DATE_FORMAT(D.CDATE,'%Y-%m-%d') where deal.busi_type = '17' and deal.ps = 'C10' and deal.trade_id = #{tradeId, jdbcType = VARCHAR} )
